# hypothesis: for c = F.R | F.W (value 3) on an enum.Flag, a checker that narrows the else branch of an is-chain to Never disagrees with CPython, which runs that branch and returns 'both'.
import enum
from typing import Literal, reveal_type


class F(enum.Flag):
    R = 1
    W = 2


def only_r(x: Literal[F.R]) -> int:
    return 1


def classify(c: F) -> str:
    if c is F.R:
        return 'R'
    elif c is F.W:
        return 'W'
    else:
        reveal_type(c)
        return 'both'


def check() -> None:
    c = F.R | F.W
    reveal_type(c)
    assert classify(c) == 'both'
    assert classify(F.R) == 'R'
    only_r(c)  # expect-error


check()
